def op_is_str(op) -> bool:
    """Mirror of createUnaryOp branch at Configuration.py:579 (isinstance(op, str)).
    True  -> op is a FuncMap key NAME (str); the str-branch resolves func = FuncMap[op].
    False -> op is assumed to be a callable; name = CustomUnaryOp, func = op.
    """
    return isinstance(op, str)
